export function getEnvVariable(key: string, defaultValue: string = ''): string {
  return process.env[key] || defaultValue;
}

import { Page, Locator, expect } from '@playwright/test';

export abstract class BasePage {
  readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  async navigateTo(url: string) {
    await this.page.goto(url);
  }

  async clickElement(locator: Locator) {
    await locator.click();
  }

  async hoverElement(locator: Locator) {
    await locator.hover();
  }

  async verifyTitle(titleOrPattern: string | RegExp) {
    await expect(this.page).toHaveTitle(titleOrPattern);
  }

  async verifyUrl(urlOrPattern: string | RegExp) {
    await expect(this.page).toHaveURL(urlOrPattern);
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class MainPage extends BasePage {
  readonly homeLink: Locator;
  readonly catalogLink: Locator;

  constructor(page: Page) {
    super(page);
    this.homeLink = page.getByRole('link', { name: 'Home' });
    this.catalogLink = page.getByRole('link', { name: 'Catalog' });
  }

  async open() {
    await this.navigateTo('https://sauce-demo.myshopify.com/');
  }

  async verifyPageTitle() {
    await this.verifyTitle(/Sauce Demo/i);
  }

  async clickHome() {
    await this.clickElement(this.homeLink);
  }

  async clickCatalog() {
    await this.clickElement(this.catalogLink);
  }
}

